pasta.gui.Button = pasta.gui.Control.extend(
{
	init : function(options) 
	{
		this._super(options);
		
		this.canvas.style.overflow = "hidden";
		
		this.leftBg = document.createElement("div");
		this.leftBg.style.position = "absolute";
		this.leftBg.style.left = "0px";
		this.leftBg.style.top = "0px";
		this.leftBg.style.width = "6px";
		this.leftBg.style.height = "36px";
		this.leftBg.style.backgroundImage = "url(img/pasta/button/left.png)";
		this.leftBg.style.backgroundPosition = "left top";
		this.canvas.appendChild(this.leftBg);
		
		this.rightBg = document.createElement("div");
		this.rightBg.style.position = "absolute";
		this.rightBg.style.top = "0px";
		this.rightBg.style.width = "6px";
		this.rightBg.style.height = "36px";
		this.rightBg.style.backgroundImage = "url(img/pasta/button/right.png)";
		this.rightBg.style.backgroundPosition = "left top";
		this.canvas.appendChild(this.rightBg);
		
		this.middleBg = document.createElement("div");
		this.middleBg.style.position = "absolute";
		this.middleBg.style.left = "6px";
		this.middleBg.style.top = "0px";
		this.middleBg.style.height = "36px";
		this.middleBg.style.backgroundImage = "url(img/pasta/button/middle.png)";
		this.middleBg.style.backgroundPosition = "left top";
		this.canvas.appendChild(this.middleBg);
		
		this.titleTop = 7;
		this.titleLeft = 0;
		
		this.title = document.createElement("div");
		this.title.style.position = "absolute";
		this.title.style.left = this.titleLeft + "px";
		this.title.style.top = this.titleTop + "px";
		this.title.style.width = "100%";
		this.title.style.height = "100%";
		this.title.style.textAlign = "center";
		this.title.innerHTML = "";
		this.title.style.userSelect = "none";
		this.canvas.appendChild(this.title);
		
		var self = this;
		
		this.font = new pasta.gui.Font();
		this.font.on("change", 
			function() 
			{ 
				if (self.enabled) 
					self.enabledColor = self.font.getColor();
				
				self.font.applyFont(self.title) 
			});
		this.font.setSize(13);
		this.font.setBold(true);
		
		this.enabledColor = this.font.getColor();
		
		this.iconCanvas = null;
		
		this.iconWidth = 24;
		this.iconLeft = 6;
		this.iconTop = 6;
		
		this.setHeight(36);
		
		this.canvas.style.cursor = "pointer";
		
		this.on("mouseOver",
			function()
			{
				self.leftBg.style.backgroundPosition = "left center";
				self.rightBg.style.backgroundPosition = "left center";
				self.middleBg.style.backgroundPosition = "left center";
			});
		
		this.on("mouseOut",
			function()
			{
				self.leftBg.style.backgroundPosition = "left top";
				self.rightBg.style.backgroundPosition = "left top";
				self.middleBg.style.backgroundPosition = "left top";
			});
		
		this.on("mouseDown",
			function()
			{
				self.leftBg.style.backgroundPosition = "left bottom";
				self.rightBg.style.backgroundPosition = "left bottom";
				self.middleBg.style.backgroundPosition = "left bottom";
				
				self.title.style.top = (self.titleTop + 1) + "px";
			});
		
		this.on("mouseUp",
			function()
			{
				self.leftBg.style.backgroundPosition = "left top";
				self.rightBg.style.backgroundPosition = "left top";
				self.middleBg.style.backgroundPosition = "left top";
				
				self.title.style.top = self.titleTop + "px";
			});
	},
	
	//------------------ Setter & Getter -----------------
	
	setEnabled : function(data)
	{
		this._super(data);
		
		this.font.setColor(this.enabled ? this.enabledColor : "#AAAAAA");
	},
	
	setImage : function(data)
	{
		if ((data == null) || (data == "default"))
		{
			this.leftBg.style.backgroundImage = "url(img/pasta/button/left.png)";
			this.rightBg.style.backgroundImage = "url(img/pasta/button/right.png)";
			this.middleBg.style.backgroundImage = "url(img/pasta/button/middle.png)";
		}
		else
		{
			this.leftBg.style.backgroundImage = "url(" + data + "/left.png)";
			this.rightBg.style.backgroundImage = "url(" + data + "/right.png)";
			this.middleBg.style.backgroundImage = "url(" + data + "/middle.png)";
		}
	},
	
	getCaption : function()
	{
		return this.title.innerHTML;
	},
	
	setCaption : function(data)
	{
		this.title.innerHTML = data;
	},
	
	setIconWidth : function(data)
	{
		this.iconWidth = data;
		
		if (this.iconCanvas != null)
		{
			this.iconCanvas.style.width = this.iconWidth + "px";
			this.iconCanvas.style.height = this.iconWidth + "px";
		}
	},
	
	setIconTop : function(data)
	{
		this.iconTop = data;
		
		if (this.iconCanvas != null)
			this.iconCanvas.style.top = this.iconTop + "px";
	},
	
	setIconLeft : function(data)
	{
		this.iconLeft = data;
		
		if (this.iconCanvas != null)
			this.iconCanvas.style.left = this.iconLeft + "px";
	},
	
	setIcon : function(data)
	{
		if (data != null)
		{
			if (this.iconCanvas == null)
			{
				this.iconCanvas = document.createElement("div");
				this.iconCanvas.style.position = "absolute";
				this.iconCanvas.style.left = this.iconLeft + "px";
				this.iconCanvas.style.top = this.iconTop + "px";
				this.iconCanvas.style.width = this.iconWidth + "px";
				this.iconCanvas.style.height = this.iconWidth + "px";
				this.iconCanvas.style.backgroundPosition = "center";
				this.iconCanvas.style.backgroundRepeat = "no-repeat";
				this.iconCanvas.style.cursor = "pointer";
				this.canvas.appendChild(this.iconCanvas);
			}
			
			this.iconCanvas.style.backgroundImage = "url(" + data + ")";
			
			this.title.style.left = (this.iconLeft + this.iconWidth + this.titleLeft) + "px";
			this.title.style.textAlign = "left";
		}
		else
		{
			if (this.iconCanvas != null)
				this.iconCanvas.style.backgroundImage = "";
			
			this.title.style.left = "0px";
			this.title.style.textAlign = "center";
		}
	},
	
	setTitleTop : function(data)
	{
		this.titleTop = data;
		
		this.title.style.top = this.titleTop + "px";
	},
	
	setTitleLeft : function(data)
	{
		this.titleLeft = data;
		
		if ((this.iconCanvas != null) && (this.iconCanvas.style.backgroundImage != ""))
			this.title.style.left = (this.iconLeft + this.iconWidth + this.titleLeft) + "px";
		else
			this.title.style.left = this.titleLeft + "px";
	},
	
	setWidth : function(data)
	{
		this._super(data);
		
		this.rightBg.style.left = (this.width - 6) + "px";
		this.middleBg.style.width = (this.width - 12) + "px";
	}
});

