		this.pnlArea.setHeight(chartHeight);
		//this.pnlArea.canvas.style.borderLeft = "1px solid #000000";
		//this.pnlArea.canvas.style.borderBottom = "1px solid #000000";
		this.pnlArea.setClipMode("hidden");
		
		this.addControl(this.pnlArea);
		
			this.pnlClient = new pasta.gui.ContainerControl();
			this.pnlClient.setLeft(0);
			this.pnlClient.setTop(0);
			this.pnlClient.setWidth(this.pnlArea.getWidth());
			this.pnlClient.setHeight(this.pnlArea.getHeight());
			this.pnlArea.addControl(this.pnlClient);
		
		this.pnlCatName = new pasta.gui.ContainerControl();
