pasta.gui.Slider = pasta.gui.Control.extend({
	init : function(){
		this._super();
		this.canvas.className = "slider shor slider-material-blue";
		this.max = 100;
		this.already = false;
	},
	setMax : function(data){
		this.max = data;
		if (this.already)
			$(this.canvas).noUiSlider("option", "max",data);
	},
	setMin : function(data) {
		this.min = data;
	},
	render : function(){
		try{
			var self = this;
			$.material.init();
			$(this.canvas).noUiSlider({
			  start: 1,
			  connect: "lower",
			  range: {
				min: 1,
				max: self.max
			  }
			});
			this.already = true;
		}catch(e){
			alert("slider " + e);
		}
	},
	addListener : function(event, listener){
		this._super(event, listener);
		var self = this;
		switch (event){
			case "change" : 
				 $(this.canvas).on("change", function(){
				 	self.emit("change", self,  $(self.canvas).val() );
				 }); 
				break;
			case "slide" :
				 $(this.canvas).on("slide", function(){
				 	self.emit("slide", self,  $(self.canvas).val() );
				 }); 
				break;
		}
	}
});
function getTextWidth(text){
	if (pasta.gui.tmpCanvas == null)
	{
		pasta.gui.tmpCanvas = document.createElement("span");
		
		pasta.gui.tmpCanvas.style.position = "absolute";
		pasta.gui.tmpCanvas.style.left = "-2000px";
		pasta.gui.tmpCanvas.style.top = "-2000px";
		
		stage.canvas.appendChild(pasta.gui.tmpCanvas);
	}
	pasta.gui.tmpCanvas.innerHTML = text;
	return pasta.gui.tmpCanvas.clientWidth + 1;
}
pasta.gui.DropDown = pasta.gui.ContainerControl.extend({
	init : function() 
	{
		this._super();
		var self = this;
		this.useService = false;
		this.edit = new pasta.gui.Edit();
		
		this.edit.on("keyUp", function(key, sender){
			try{
				self.dropButton.canvas.className = 'glyphicon glyphicon-chevron-up';
				sender.isDown = true;
				self.listItem.setVisible(true);
				if (self.useService){
					self.callService();
				}else {
					if (sender.getText().length == 0){
						for (i = 0; i < self.listItem.controls.length;i++){
							var ctrl = self.listItem.controls[i];
							ctrl.setVisible(true);
						}
					}
					var totalHeight = 0;
					for (i = 0; i < self.listItem.controls.length;i++){
						var ctrl = self.listItem.controls[i];
						if (ctrl.caption.indexOf(sender.getText()) == -1)
							ctrl.setVisible(false);
						else {
							ctrl.setVisible(true);
							totalHeight += 42;
						}
					}
					if(totalHeight > 210)
						self.listItem.setHeight(210);
					else self.listItem.setHeight(totalHeight);
				}
			}catch(e){
				console.log(e);
			}
		});
			this.dropButton = new pasta.gui.Control();
			this.dropButton.isDown = false;
			this.dropButton.canvas.className = 'glyphicon glyphicon-chevron-down';
			this.dropButton.canvas.style.color = "grey";
			this.dropButton.setWidth(20);
			this.dropButton.on("click", function(sender, obj, e){	
				try{
					if (!sender.isDown){
						self.dropButton.canvas.className = 'glyphicon glyphicon-chevron-up';
						self.listItem.setVisible(true);
						self.listItem.setWidth(self.width);
						self.listItem.setTop(20);
					}else {
						self.dropButton.canvas.className = 'glyphicon glyphicon-chevron-down';
						self.listItem.setVisible(false);
						self.listItem.setWidth(self.width);
					}	
					sender.isDown = !sender.isDown;		
								
				}catch(e){
					console.log(e);
				}
			});
			this.addControl(this.edit);
			this.addControl(this.dropButton);
			
			this.listItem = new pasta.gui.ContainerControl();
			this.listItem.clientCanvas.style.position = "absolute";
			this.listItem.clientCanvas.className = "menu-wrap";
			this.listItem.canvas.style.overflow = "hidden";
			this.listItem.clientCanvas.style.background = "#fff";
			this.listItem.canvas.style.boxShadow = "0px 1px 5px #888";
			this.listItem.canvas.style.zIndex = 9;
			this.listItem.setVisible(false);
			this.listItem.setHeight(100);
			
			
			this.addControl(this.listItem);
		
	},
	setMode: function(mode){
		switch (mode){
			case 0 : this.dropButton.canvas.className = 'glyphicon glyphicon-chevron-down';
			break;
			case 1 : this.dropButton.canvas.className = 'glyphicon glyphicon-search';
			break;
		}
	},
	setWidth: function(data){
		this._super(data);
		this.edit.setWidth(data - 20);
		this.dropButton.setLeft(data - 20);
		this.listItem.setWidth(data);
	},
	setHeight : function(data){
		this._super(data);
		this.edit.setHeight(data);
		this.dropButton.setHeight(data);
		this.listItem.setTop(data);
	},
	displayList: function(){
		
	},
	setPlaceHolder: function(data){
		this.edit.setPlaceHolder(data);
	},
	addItem: function(caption, id){
		try{
			var self = this;
			var item = new pasta.gui.ContainerControl();
			if (getTextWidth(caption) < this.listItem.width)
				var w = this.listItem.width;
			else if (getTextWidth(caption) < 300)
				var w = getTextWidth(caption);
			else var w = 300;
			
			this.listItem.setWidth(w);
			item.setHeight(42);
			item.setWidth(w);
			item.canvas.style.position = "relative";
			item.canvas.className = "saku-item";			
		
			var label = new pasta.gui.Label();
			label.setLeft(20);
			label.setWidth(w  - 40);
			label.setTop(16);
			label.setCaption(caption);
			item.addControl(label);
			if (id == undefined) id = caption;
			item.caption = caption;
			item.id = id;
			item.on("click", function(sender){
				self.edit.setText(sender.caption);
				self.selectedId = sender.id;
				self.listItem.setVisible(false);
				self.dropButton.canvas.className = 'glyphicon glyphicon-chevron-down';
			});
			this.listItem.addControl(item);
			
			if(this.listItem.controls.length * 42 > 210)
				this.listItem.setHeight(210);
		}catch(e){
			console.log(e);
		}
	},
	addListener: function(event, listener){
		var self = this;
		if (event == "change"){
			this.canvas.onchange = function(e){
				if (!e) e = window.event; 
				self.emit("change", self, $(self.canvas).val());
			};
		}
		this._super(event, listener);
	},
	getSelectedItem: function(){
		return this.selectedId;
	},
	getText: function(){
		return this.edit.getText();
	},
	setService: function(service,fieldKey, fieldNama, offset){
		try{
			this.useService = true;
			var self = this;
			this.service = service;
			this.fieldKey = fieldKey;
			this.fieldNama = fieldNama;
			this.offset = offset;
			this.callService();
		}catch(e){
			console.log(e);
		}
	},
	callService: function(){
		var self = this;
		self.useService = true;
		application.services[self.service](this.edit.getText(), this.offset, function(data){
				self.listItem.clear();
				try{
					//if (data.length <= self.offset && data.length != 0)
					//	self.useService = false;
					console.log(data.length);
					for (var i = 0; i < data.length; i++){
						console.log(data[i][self.fieldNama]);
						self.addItem(data[i][self.fieldNama], data[i][self.fieldKey]);
					}
				}catch(e){
					console.log(e);
				}
			});
	}
});
