mykitab.paper = pasta.gui.Control.extend({
	init : function(){
		this._super();
		//this.canvas.className = "paper-content";
		this.canvas.style.userSelect = "none" ;
		this.canvas.style.webkitUserSelect = "none";
		this.canvas.style.mozUserSelect = "none";
		this.canvas.className = "mykitab-secondary";
        //this.canvas.style.lineHeight = "1.240em";
        this.canvas.style.fontSize = "15px";
		//this.canvas.style.textAlign="justify";
		var self = this;
		
	},
	clearStyle : function(){
		var content = this.content;
		content = content.replace(/\[/g,"");
		content = content.replace(/\]/g,"");
		this.canvas.innerHTML = content;
	},
	setContent : function(content){
		try{
            this.scroll = false;
			this.content = content.trim();
			content = content.replace(/\[/g,"");
			content = content.replace(/\]/g,"");
			this.canvas.innerHTML = content;
            this.textHeight = this.getTextHeight();
            
			beautify(this.canvas, this.content);
			
		}catch(e){
			console.log(e);
		}
	},
	refresh : function(){
		var content = this.content;
		content = content.replace(/\[/g,"");
		content = content.replace(/\]/g,"");
		this.canvas.innerHTML = content;
		beautify(this.canvas, this.content);
		
	},
	getTextHeight : function()
	{
		return parseInt(window.getComputedStyle($(this.canvas)[0]).fontSize,10);
	},
});
function addSpan(elem){
	if(elem.nodeType == elem.TEXT_NODE) {
		var range = elem.ownerDocument.createRange();
		range.selectNodeContents(elem);
		var currentPos = 0;
		var endPos = range.endOffset;
		var startSelect = false;
		var indexSelect = 0;
		
		var match = [];
		while(currentPos+1 < endPos) {
		  range.setStart(elem, currentPos);
		  range.setEnd(elem, currentPos+1);
		  if (range.toString() == "["){
		  		startSelect = true;
		  		indexSelect = currentPos;
		  }else if (range.toString() == "]"){
		  		startSelect = false;
		  		var highlight = document.createElement('span');
				highlight.className = 'sanad';	
				
				var wordNode = elem.splitText(indexSelect);
				wordNode.splitText(currentPos - indexSelect );
				var wordClone = wordNode.cloneNode(true);
				highlight.appendChild(wordClone);
				
				wordNode.parentNode.replaceChild(highlight, wordNode);
				return 1;
		  }else if (range.toString() == '"' && !startSelect){
		  		startSelect = true;
		  		indexSelect = currentPos;
		  }else if (range.toString() == '"' && startSelect){
		  		startSelect = false;
		  		match.push({startIndex: indexSelect, length : currentPos - indexSelect});
		  		var highlight = document.createElement('span');
				highlight.className = 'sanad';	
				var wordNode = elem.splitText(indexSelect);
				wordNode.splitText(currentPos - indexSelect);
				var wordClone = wordNode.cloneNode(true);
				highlight.appendChild(wordClone);
				wordNode.parentNode.replaceChild(highlight, wordNode);
				return 1;
		  }
		  currentPos += 1;
		}
	}else {
		for(var i = 0; i < elem.childNodes.length; i++) {
		  	var range = elem.childNodes[i].ownerDocument.createRange();
		  	range.selectNodeContents(elem.childNodes[i]);
		  	//console.log(elem.childNodes[i]);
			i += addSpan(elem.childNodes[i]);
		}
		return 0;
	}
	/**/
}
function beautify(elem, content){
	var tmp = "";
	var matan = false;
	var startSelect = false;
	for (var i = 0; i < content.length;i++){
		if (content[i] == "["){
			//tmp += "<span class='sanad'>";
			startSelect = true;
		}else if (content[i] == "]"){
			//tmp += "</span>";
			//console.log(tmp);
			$(elem).highlight(tmp, {className:"sanad"});
			tmp = "";
			startSelect = false;
		}else if (content[i] == '"' && !matan){
			//tmp += "<span class='matan'>";
			tmp += content[i];
			matan = true;
			startSelect = true;
		}else if (content[i] == '"' && matan){
			tmp += content[i];
			matan = false;
			//console.log(tmp);
			$(elem).highlight(tmp, {className:"matan"});
			startSelect = false;
			tmp = "";
		}else if (startSelect){
			tmp += content[i];
		}
	}
	return tmp;
}
