mykitab.screenHome = pasta.gui.ContainerControl.extend({
	init : function(){
		this._super();
		var w = $(window).width();
		var h = $(window).height();
		this.headerPnl = new mykitab.HeaderKitab();
		this.headerPnl.setHeight(56);
		this.headerPnl.setWidth( "100%" );
		this.headerPnl.lLabel.setTop( 16);
		this.addControl(this.headerPnl);
		this.headerPnl.setCaption("Ensiklopedi Hadits - Kitab 9 Imam");
		this.canvas.style.background = "#ffffff";

		this.container = new pasta.gui.ContainerControl();
			this.container.canvas.style.background = "#ffffff";
			this.container.setTop(56);
			this.container.setWidth( w );
			this.container.setHeight($(window).height() - 56 - 56);
			this.container.canvas.style.bottom = 0;
			
			this.container.canvas.style.overflow = "hidden";
			this.container.clientCanvas.style.overflowX ="hidden";
			this.container.setTop(56);
			this.bg = new pasta.gui.Picture();
			this.bg.setWidth( w );
			this.bg.setTop(0);
			this.bg.setHeight( this.container.height);
			this.bg.setImage("/img/bg.jpg");
			this.bg.setMode(6);
			this.container.addControl(this.bg);
		this.containerBuku = new pasta.gui.ContainerControl();
		this.containerBuku.setWidth(this.container.width);
		this.containerBuku.setHeight(this.container.height);

			
		this.container.addControl( this.containerBuku );
		this.addControl(this.container);
		this.on("resize", () => {
			try{
				var w = $(window).width();
				var h = $(window).height();
				this.headerPnl.setWidth( w );
				this.container.setWidth( w )
				this.container.setHeight( h - 56 - 56 );
				this.bg.setHeight( this.container.height);
				this.bg.setWidth(  w );
				this.containerBuku.setWidth(this.container.width);
				this.containerBuku.setHeight(this.container.height);
				this.rearrange();
			}catch(e){
				console.log(e);
			}
		});
		
		this.rearrange();
	},
	rearrange: function(){
		this.containerBuku.clear();
		var w = this.containerBuku.width;
		var h = this.containerBuku.height;
			var wBuku = w / 3;
			var hBuku = this.container.height / 3;
			var left = 0;
			var top = 0;
			var ctx = 0;
			$.each(haditsSetting, (imam, buku) => {
				var ctrl = this.addItem(imam,buku, wBuku, hBuku);
				
				if (ctx % 3 == 0){
					left = 0;
					if (ctx > 0){
						top += hBuku;	
					}
					
				}else {
					left += wBuku;
				}
				ctrl.setLeft(left);
				ctrl.setTop(top);
				this.containerBuku.addControl(ctrl);
				ctx++;
			});
	},
	addItem : function(imam, buku, wBuku, hBuku){
				var ctrl = new pasta.gui.ContainerControl();
				ctrl.setWidth(wBuku);
				ctrl.setHeight(hBuku);
				ctrl.clientCanvas.style.padding = "10px";
					var cover = new pasta.gui.Control();
					cover.setWidth(wBuku - 20);
					cover.setTop(0);
					cover.setLeft(10);
					cover.setHeight(hBuku);
					cover.canvas.style.alignItems = "flex-end";
					cover.canvas.style.justifyContent = "center";
					cover.canvas.style.display = "flex";
					cover.canvas.innerHTML = "<a href='https://hadits.in/"+ imam +"/1'><img src='/img/"+imam+".png' style='width:100%;height:auto;' /></a>";
					cover.on("click",() => {
						window.location.href = "https://hadits.in/"+ imam +"/1";
					});
					// cover.setMode(6);
					ctrl.addControl(cover);
					var judul = new pasta.gui.Label({rect: {x:0,y:cover.height - 20, width:cover.width + 20, height:20}});
					judul.setCaption(buku.buku);
					judul.font.setSize(12);
					judul.setAlign("center");
					judul.font.setColor("white");
					judul.canvas.style.backgroundImage = "url('/img/judul.png')";
					judul.canvas.style.backgroundRepeat = "no-repeat";
					judul.canvas.style.backgroundSize = "cover";
					ctrl.addControl(judul);
		return ctrl;
	}
});
